// PICO icon registry: stable string keys -> SVG asset + bilingual label.
// Generated by brand/scripts/build_icons.py. Mirrors LumbungIconRegistry.
//
// TARGET: packages/pico_ui_kit/lib/src/foundations/icons/pico_icon_registry.dart
// Assets: copy brand/icons/{mono,duotone}/*.svg to packages/pico_ui_kit/assets/icons/
// and declare them in the package pubspec. Render with flutter_svg:
//
//   final icon = PicoIconRegistry.resolve('state.recovered')!;
//   SvgPicture.asset(icon.mono, package: 'pico_ui_kit',
//       colorFilter: ColorFilter.mode(color, BlendMode.srcIn),
//       semanticsLabel: icon.label(locale));   // or excludeFromSemantics: true next to visible text
//
// Persist the KEY, never an index. Unknown key -> null; render the `info` icon.

/// One registered icon asset. Named PicoBrandIconAsset: `PicoIcon` is the kit widget and `PicoIconAsset` is the asset_core contract.
class PicoBrandIconAsset {
  const new(this.file, this.labelId, this.labelEn);

  /// File stem, e.g. `pico-state-recovered`.
  final String file;
  final String labelId;
  final String labelEn;

  String get mono => 'assets/icons/mono/$file.svg';
  String get duotone => 'assets/icons/duotone/$file.svg';

  /// Bahasa Indonesia first; English when the locale language is `en`.
  String label(String languageCode) => languageCode == 'en' ? labelEn : labelId;
}

